package io.github.mhaberler.adsbdongle.rtlsdr;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import org.junit.Test;

/** Parity with webapp/src/modes-demod.ts on the shared fixture (generated by webapp/src/fixtures/synth-iq.ts). */
public class ModeSDemodTest {
    // Gradle runs unit tests with the module directory (app/android/app) as working directory.
    private static final Path FIXTURES = Paths.get("../../../webapp/src/fixtures");

    @Test
    public void fixtureMatchesTypeScript() throws Exception {
        byte[] iq = Files.readAllBytes(FIXTURES.resolve("adsb-2msps.u8"));
        List<String> expected = Arrays.asList(
            new String(Files.readAllBytes(FIXTURES.resolve("adsb-2msps.txt")), StandardCharsets.UTF_8).trim().split("\n"));
        assertEquals(expected, new ModeSDemod().push(iq, iq.length));
    }

    @Test
    public void fixtureSplitAcrossBuffers() throws Exception {
        byte[] iq = Files.readAllBytes(FIXTURES.resolve("adsb-2msps.u8"));
        List<String> expected = Arrays.asList(
            new String(Files.readAllBytes(FIXTURES.resolve("adsb-2msps.txt")), StandardCharsets.UTF_8).trim().split("\n"));
        ModeSDemod d = new ModeSDemod();
        List<String> got = new ArrayList<>();
        for (int o = 0; o < iq.length; o += 1000) {
            byte[] chunk = Arrays.copyOfRange(iq, o, Math.min(iq.length, o + 1000));
            got.addAll(d.push(chunk, chunk.length));
        }
        byte[] tail = new byte[1000];
        Arrays.fill(tail, (byte) 128);
        got.addAll(d.push(tail, tail.length));
        assertEquals(expected, got);
    }

    @Test
    public void tunerMathMatchesTypeScript() {
        long lo = RtlSdrDriver.ADSB_FREQ_HZ + 3_570_000L;
        long[] p = RtlSdrDriver.pllPlan(lo, 28_800_000L, 2, 2);
        assertEquals(1, p[4]);
        double f = 2.0 * 28_800_000L * (p[2] + p[3] / 65536.0) / p[0];
        assertTrue(Math.abs(f - lo) < 1000);
        assertArrayEquals(new int[] {15, 14, 496}, RtlSdrDriver.gainSteps(RtlSdrDriver.GAIN_TENTH_DB));
        assertEquals(20, RtlSdrDriver.firBytes().length);
    }
}
